@web.get("/api/identities")
def identities():
    service().bo.record("repair.identities", "return", lambda: {"inputs": {}, "outputs": {"count": len(IDENTITIES)}})
    return jsonify(IDENTITIES)


@web.get("/api/tickets")
def ticket_list():
    return jsonify(service().list_tickets())


@web.post("/api/tickets")
