def confirm(ticket_id: int):
    return reply(service().confirm(ticket_id, actor()))


@web.errorhandler(ValueError)
def handle_error(error):
    if request.is_json or request.path.startswith("/api/"):
        return jsonify({"error": str(error)}), 409
    return redirect(url_for("index", actor_id=request.values.get("actor_id", "u1"), message="操作未完成：身份、单据状态或内容不符合要求。"))


@web.get("/api/stategraph")
def bo_stategraph_query():
    with service().store.lock:
        # This observer read deliberately bypasses instrumented business queries.
        from sqlalchemy import select
        from .models import tickets
        with service().store.engine.connect() as connection:
            rows = [dict(row) for row in connection.execute(select(tickets).order_by(tickets.c.id)).mappings()]
        journal = service().bo.journal()
        bases = service().bo.state_bases()
    return jsonify(bo_public_projection(web.config["BO_MODEL"], service().build_id, rows, journal, bases))


