"""Exercise the installed renderer's actual curve and camera-relative caption helpers."""

import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = r'''
import assert from 'node:assert/strict';
import * as T from './static/graph/spatial-three.vendor.js';
import { edgeCurve } from './static/graph/spatial-paths.js';
import { regionLabelAnchor } from './static/graph/spatial-labels.js';
let curves=0, views=0;
for (const y of [0,260,520]) {
 for (const [a,b] of [[{x:0,y,z:0},{x:280,y,z:120}],[{x:10,y,z:20},{x:10,y,z:20}]]) {
  const curve=edgeCurve(a,b);
  for(let i=0;i<=100;i++) assert.ok(Math.abs(curve.getPoint(i/100).y-y)<1e-9);
  curves++;
 }
}
const volume={center:{x:0,y:260,z:0},radius:160}, anchors=[];
for(const position of [[0,1100,1],[700,650,900],[-650,500,600]]) {
 const camera=new T.PerspectiveCamera(42,16/9,1,10000);
 camera.position.fromArray(position); camera.lookAt(0,260,0); camera.updateMatrixWorld();
 const project=(p)=>{const v=new T.Vector3(p.x,p.y,p.z).project(camera);return{x:(v.x+1)*640,y:(1-v.y)*360,depth:v.z};};
 const anchor=regionLabelAnchor(volume,project);
 let bottom=-Infinity;
 for(let i=0;i<4096;i++){const angle=i/4096*Math.PI*2;bottom=Math.max(bottom,project({x:Math.cos(angle)*160,y:260,z:Math.sin(angle)*160}).y);}
 assert.ok(anchor.y>=bottom+6.5&&anchor.y<=bottom+7.5);
 anchors.push(anchor); views++;
}
assert.notDeepEqual(anchors[0],anchors[1]);
console.log(JSON.stringify({valid:true,curves,sampledPoints:curves*101,cameraViews:views,circumferenceSamples:views*4096,labelOffsetPx:7}));
'''

if __name__ == "__main__":
    result = subprocess.run(["node", "--experimental-default-type=module", "--input-type=module", "-e", SCRIPT], cwd=ROOT, capture_output=True, text=True, encoding="utf-8", timeout=30)
    if result.returncode:
        raise SystemExit(result.stderr)
    print(result.stdout.strip())

sources.tooling/bo_build.py:
"""Derive source/data projections around the one canonical executable declaration."""

import json
import os
from pathlib import Path
import bo_environment
from app.storage import Store
from code_structure import scan, enrich
from bo_observer.data.sync import synchronize
from bo_observer.observation.observation_scope import endpoint_paths

ROOT = Path(__file__).resolve().parents[1]


def write(name, value):
    path = ROOT / name
    path.parent.mkdir(parents=True, exist_ok=True)
    raw = json.dumps(value, ensure_ascii=False, indent=2) + "\n"
    if not path.exists() or path.read_text(encoding="utf-8") != raw:
        path.write_text(raw, encoding="utf-8")


def machine():
    path = ROOT / "bo_stategraph/project.json"
    if path.exists():
        return json.loads(path.read_text(encoding="utf-8"))["model"]["machine"]
    states = ["pending", "in_progress", "awaiting_confirmation", "completed"]
    return {"engine": "bo.fsm", "version": "1", "states": states, "values": states, "initial": "pending", "state_type": "enum", "labels": {"pending": "待接单", "in_progress": "处理中", "awaiting_confirmation": "待用户确认", "completed": "已完成"}, "context": {"submitter_id": {"type": "string"}, "technician_id": {"type": "string"}, "result_length": {"type": "integer", "min": 0}}, "events": {"claim": {"payload": {"actor_id": {"type": "string"}}}, "record_result": {"payload": {"actor_id": {"type": "string"}, "result_length": {"type": "integer", "min": 0}}}, "confirm": {"payload": {"actor_id": {"type": "string"}}}}, "guards": {"is_technician": "当前身份是维修员", "is_assignee": "当前身份是接单维修员", "has_result": "处理结果非空", "is_submitter": "当前身份是提交人"}, "transitions": [{"trigger": "claim", "source": "pending", "dest": "in_progress", "conditions": ["is_technician"]}, {"trigger": "record_result", "source": "in_progress", "dest": "awaiting_confirmation", "conditions": ["is_technician", "is_assignee", "has_result"]}, {"trigger": "confirm", "source": "awaiting_confirmation", "dest": "completed", "conditions": ["is_submitter"]}]}


def build():
    cfg = json.loads((ROOT / "sync.json").read_text(encoding="utf-8"))
    cfg["code_files"] = ["app/__init__.py", "app/domain.py", "app/models.py", "app/storage.py", "app/policy.py", "app/server.py", "app/ports.py", "bo_stategraph/workflow.py", "bo_stategraph/query.py", "bo_stategraph/bo_pathcheck.py", "integrations/__init__.py", "integrations/bo_adapter.py", "integrations/bo_serve.py"]
    cfg["model"] = "bo_stategraph/project.json"
    cfg["watch_files"] = sorted(set(cfg["watch_files"] + ["tests/test_spatial_math.py", "ownership.json", "bo_core_run.py", "tests/test_engineering.py", "tests/test_evidence.py", "tooling/__init__.py", "tooling/bo_build.py", "tooling/bo_observe.py", "bo_environment.py", "export_model.py", "validate.py", "bo_stategraph/bo_executor.py", "templates/index.html", "requirements.txt", "AGENTS.md"]))
    evidence_command = ["{python}", "-B", "tests/test_evidence.py"]
    if evidence_command not in cfg["test_commands"]:
        cfg["test_commands"].append(evidence_command)
    engineering_command = ["{python}", "-B", "tests/test_engineering.py"]
    if engineering_command not in cfg["test_commands"]:
        cfg["test_commands"].append(engineering_command)
    spatial_command = ["{python}", "-B", "tests/test_spatial_math.py"]
    if spatial_command not in cfg["test_commands"]:
        cfg["test_commands"].append(spatial_command)
    cfg["source_scope"]["exclude"].update({"bo_core_run.py": "Tracked standalone core launcher; actual business methods remain indexed under app/", "tooling/**": "Tracked graph generator and independent scenario/check utilities; these are not application endpoints", "bo_environment.py": "Tracked local runtime import-path setup", "export_model.py": "Tracked offline native metadata exporter", "validate.py": "Tracked normal verification entrypoint"})
    write("sync.json", cfg)
    index = scan(ROOT, cfg["code_files"])
    if index["errors"]:
        raise ValueError(index["errors"])
    declaration = machine()
    nodes, edges = [], []
    def node(ident, kind, label, source=None, parent=None, capture=None, **extra):
        item = {"id": ident, "kind": kind, "label": label, "summary": label, "capture": capture or {"in": {}, "out": {}}, **extra}
        if source:
